// Generated by scripts/gen-skills.mjs from skills/**/*.md (D-105). Do not edit.
export const skills = {
  "accord/SKILL.md": "---\nname: accord\ndescription: Use when starting any work in an accord repository, when seeing where work stands, or when continuing a ticket. Shows the dashboard, continues or picks up a ticket, and classifies a new request into a lane.\nlicense: MIT\nkind: skill\nloads: [accord/ids.md, accord/worktree.md, shared/ask.md]\n---\n\n## Dashboard: `/accord` with no argument\n\n1. Run `accord worktree clean`, then `accord dashboard`. It reads you from\n   `git config user.email` and prints every section ranked and capped, one\n   count line, and the actions that apply. When it exits 2, show its message\n   and stop.\n2. Show both outputs verbatim in a code block. Never reorder, cut, merge, or\n   add to it, and never build a section from `accord status --json`.\n3. Offer the actions its last line names: Continue, Pick up, New request.\n\n## A ticket named: `/accord pick-up <id>`, `/accord continue <id>`\n\nAn action applies only when the whole text after it is exactly one\nticket id, the id of a ticket in `accord/tickets/`, an id that\n`accord status --json` lists with a `branch`, or for Continue a ticket\n`accord worktree open <id> --continue` finds; with none,\n`/accord continue ST-99` is a New request. Then run Pick up or\nContinue below on that ticket, without showing the dashboard first. Continue on a ticket nobody has claimed\nsays so, offers Pick up, and never claims it. Any other text starts a\nNew request whose text is the whole text after `/accord`: for\n`/accord continue the refactor` it is `continue the refactor`, and\n`/accord continue ST-2 now` is a new request too.\n\n## Continue\n\n1. Run `accord worktree open <id> --continue` unless it just ran; follow\n   `./worktree.md`. The active ticket is its `branch` from\n   `accord status --json`, read from git, never from memory.\n2. Run `accord anchor`. It prints the stage and the position from the ledger,\n   then the owner's words verbatim.\n3. If `accord/tickets/<id>/debug.md` exists and its last `## ` heading is\n   not `## Resolved`, load `accord-debug` and resume there.\n4. Otherwise load the stage skill for the stage it prints: `intent` →\n   `accord-approach` at step 5, the owner's yes, when the ticket's\n   `## Approach` is already written, otherwise `accord-intent`; `plan` →\n   `accord-plan`, `build` → `accord-build`, `review` → `accord-review`,\n   `verify` → `accord-verify`; `done` → `accord-verify` at step 6 when\n   `git status --porcelain` on the ticket file or its `verification.md`\n   prints anything, otherwise say the ticket is done and offer the\n   dashboard. Resume at the step the anchor names. Never re-run a task\n   the ledger records.\n\n## Pick up\n\nRun `accord worktree open <id>`: it makes its `branch` from\n`accord status --json` and commits `claim: <id>` on it. Follow\n`./worktree.md`; it says when to push it (the pushed branch is the claim).\n\n## New request: `/accord <request>`\n\nPropose a lane with its reason, out loud. The owner may override.\n\n| Lane | Example |\n|---|---|\n| S: small fix | bug, copy change, one flag |\n| M: feature | one story |\n| L: epic | 3 to 10 related stories |\n| P: project | greenfield |\n\nAny of these lifts S to M: new user-visible behaviour; a public interface or\nschema changes; auth, money, or data deletion is touched; more than one\nplausible reading; more than about three files expected.\n\n- **S.** Write back two lines in chat, `Understood: …` and `Done when: …`.\n  Proceed without waiting only when the request has a concrete anchor (file,\n  symbol, error message, or expected behaviour) and one plausible reading;\n  otherwise ask exactly one question and wait. Do the change in the main\n  session and run the affected tests. Run `git add -N` on every new file\n  so the diff shows it, then write the two lines and the `git diff` of\n  the change into a file outside the working tree, dispatch\n  one fresh `accord-reviewer`, lens `both`, with its path, and give a short\n  report in chat.\n- **M.** Run `accord new ticket <id> --lane M --worktree`; when config.yml has\n  `people`, follow `./ids.md` and run `accord new ticket --type <story|bug>\n  --lane M --worktree` with no id instead. It writes the ticket on its\n  `branch` from `accord status --json`, commits it and pushes it; follow\n  `./worktree.md`, and push it as that file says when the push fails.\n- **L and P.** Not built yet. Say so, and propose splitting the work into\n  lane M tickets linked by `depends_on`.\n\n## Rules\n\n- A lane only rises. Complexity found mid-task lifts the lane: stop, say so,\n  and re-enter at the new lane's first incomplete stage. A lane never drops.\n- A ticket without `lane:` follows the 0.1.0 contract. Offer to add `lane: M`\n  and the lane headings; do it only on a yes.\n- In lane M the main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision on a\n  ticket is a Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`.\n  Read `./ask.md` before any question to the owner.\n",
  "accord/ids.md": "---\nkind: reference\n---\n\n# Ticket ids, people, and dropping\n\nRead this when config.yml has `people`. Register only when `people` exists, never create it.\n\n## Assigning\n\nFetch first with\n`git -c credential.interactive=never -c core.sshCommand=\"ssh -o BatchMode=yes\" fetch`;\non failure say so and continue, since only refs already in the clone are read.\nThen run `accord new ticket --type <story|bug> --lane <lane>` with no id, adding `--worktree` when the lane is M, and use the id it prints.\nNever retry with an id.\n\n## When your email is not registered\n\nLook for it on other branches with\n`git -c credential.interactive=never -c core.sshCommand=\"ssh -o BatchMode=yes\" log --all -S \"<email>\" --oneline -- accord/config.yml`\nand `git show <commit>:accord/config.yml` (the same prefix, since reading blobs can fetch in a partial clone),\nand reuse those initials. If that lookup fails or finds nothing, ask the owner for initials, 2 to 4 capital\nletters, suggested from `git config user.name`. Add `\"<email>\": <INITIALS>` under `people`; when the file has\n`people: {}`, write `people:` with the entry on the next line, indented two spaces, in its place.\nRecognition names tickets and is never a gate. When the command says the initials belong to someone else,\nask for other initials.\n\n## Merge conflicts under `people`\n\nKeep each email once, comparing emails without regard to case. When the two sides give one email different\ninitials, or two different emails the same initials, ask the owner which to keep.\n\n## Dropping instead of renaming\n\nA ticket's type never changes and its id is never renamed. To change the type:\n\n1. Set `status: dropped` with a `## Dropped` reason, commit and merge that. Never delete a claim branch to drop a ticket.\n2. Create the new ticket with `accord new ticket --type <the other type> --lane <lane>`, always passing\n   `--lane`: the dropped ticket's lane, except `L` for a new epic and `M` for a story or bug made from an epic.\n3. Copy into it the dropped ticket's frontmatter keys `title`, `ui`, `design`, `parent`, `depends_on` and\n   `tracker`, where present, and every section below its frontmatter except `## Dropped`; the copied sections\n   replace the template's sections.\n4. Never copy `id`, `type`, `status`, `lane`, `approved_hash`, `ac_hash`, `verified`, `verified_hash` or\n   `verified_commit`. When the change is between an epic and a story or bug, do not copy `parent` either.\n5. In the copied sections, remove every `@test:<id>` tag from the scenarios and change the gherkin\n   `Feature: <old id>` line to the new id.\n6. The owner approves the new ticket again.\n",
  "accord/worktree.md": "---\nkind: reference\n---\n\n# Working a ticket in its own worktree\n\nOnly a session rooted in a ticket's worktree works that ticket, so no session ever switches tickets.\n\nFor Continue, `accord worktree open <id> --continue` also finds a ticket whose file is only on its claim\nbranch, here or on `origin`. When it exits 2 with a line starting `not a ticket:`, the text is a New\nrequest. A line starting `not claimed:` means nobody has claimed the ticket: say so, offer Pick up, and\nnever claim it.\n\nWhen Pick up's `accord worktree open <id>` exits 2 with a line starting `claimed:`, another person\nholds the claim: push nothing, show the message and stop. Offer `/accord continue <id>` only when the\nowner means to work on the ticket with them. When `accord worktree open <id>` did not refuse with `claimed:`, push the claim with\n`git push -u origin <branch>` before anything else, even when a setup command failed.\n\nWhat `accord worktree open <id>` and `accord new ticket --worktree` print:\n\n- A line `pruned <path>: <reason>`: git dropped its record of a worktree whose folder is gone; show the\n  line verbatim and go on with the other lines.\n- A line `stop:`: show the two lines after it verbatim, the worktree's path and the line to type in a\n  session opened in that folder, then stop. Never change directory into the worktree, never edit a file\n  there except the people entry below, and never start the next stage from this session.\n- `held: <id> by this session`: this session holds the ticket; go on with the next step.\n- `not held:`: this tool does not refuse a second session yet; say so in one line and go on with the\n  next step.\n- Exit 2 naming the session that holds the ticket: show the message and stop, editing nothing.\n- Exit 2 naming a setup command: show the message and stop. The worktree is kept; once the owner fixes\n  the command, `/accord continue <id>` in a session opened there runs every setup command again.\n- Any other exit 2: show the message and stop.\n\nSetup commands can take minutes: run these commands with the longest timeout your tool allows.\n\nWhen `./ids.md` had you add an entry under `people` before `accord new ticket --worktree`, carry it to the\nworktree before you stop: add the same entry to `<path>/accord/config.yml`, run\n`git -C \"<path>\" commit -m \"people: <email>\" -- accord/config.yml` and\n`git -C \"<path>\" push -u origin <branch>`, then remove that entry, and only that entry, from\n`accord/config.yml` here, leaving every other line of the file as it is.\n\nWhen `accord new ticket --worktree` says the push failed, it prints no `stop:` line: carry any people\nentry as above, run the push it names, and once it succeeds, run `accord worktree open <id> --continue`\nand follow the `stop:` line it prints. When that push fails again, show git's message and stop.\n\n`accord worktree clean` runs only from `/accord` with no argument, never from Pick up or Continue. At the\ndashboard its lines are shown verbatim with the dashboard's.\n",
  "approach/SKILL.md": "---\nname: accord-approach\ndescription: Use when a lane M ticket has its intent and acceptance criteria and needs an approach. Chooses the lightest approach that works, has a critic argue against it, and takes the owner's explicit yes before accord approve.\nlicense: MIT\nkind: skill\nloads: [shared/ask.md]\n---\n\nThis stage chooses how the ticket will be built, lightest first, and takes\nthe owner's yes before anyone plans. You run it in the main session.\n\n## Steps\n\n1. Run `accord anchor`.\n\n2. **Options.** Dispatch `accord-architect` with the path of\n   `accord/tickets/<id>.md`. It runs an impact analysis (callers,\n   interfaces, tests, config, exports the change must reach) and proposes\n   two or three options in ladder order. The first option is always the\n   lightest that works. Every added layer of complexity names the\n   acceptance criterion or constraint that requires it, or is dropped.\n\n3. **Critique.** The chosen option is the one the architect marks\n   `Recommended`, unless the owner has already picked another. Dispatch\n   `accord-critic` in a fresh context, mode `approach`, with the path of\n   the ticket file and the chosen option's text only (its name and what it\n   does), never the architect's reasoning, risk line, or `Recommended`\n   line, so its review stays independent. It argues the strongest case\n   against the chosen option and checks it against Vetoes, Decisions, and\n   Corrections. This runs for every ticket in lane M and above.\n   If a Must finding would break a Veto, Decision, or Correction, that\n   option is out: take the first option in the architect's ladder order\n   that is not yet ruled out, and run the critic again on it. If no option\n   is left, ask the owner. When the ticket touches auth, money, migration,\n   or data deletion, ask the critic for three concrete failure scenarios as\n   well.\n\n4. **Write `## Approach`** in `accord/tickets/<id>.md`, about fifteen lines:\n\n   - chosen option and why;\n   - rejected options and why;\n   - affected areas;\n   - risks: every critic finding the chosen option keeps, Must findings\n     first, so the owner approves with them in view; for a ticket that\n     touches auth, money, migration, or data deletion, each of the\n     critic's three failure scenarios and how it is undone;\n   - test strategy: which criterion is tested at which layer.\n\n   Commit `accord/tickets/<id>.md`.\n\n5. **The owner's yes.** Run `accord show <id> --approval`; if it fails, stop and tell\n   the owner. Paste its output, which holds every approved section, unchanged, as Markdown, not inside a code\n   block; below it put a horizontal rule, a heading \"In plain words\" written in the chat language, and one line\n   per scenario that begins with its ac-n and says in plain words what it means; and ask for an explicit yes.\n   The question\n   names the text above it and `accord/tickets/<id>.md`. Say that the yes\n   also approves the ticket's Intent, acceptance criteria, Vetoes,\n   Decisions, and Corrections as written: the approval covers them all. On\n   yes, run\n   `accord approve <id>`, then `accord gate ready <id>` and work from what it\n   prints. Then commit the ticket, with `approved_hash:` and `ac_hash:` in\n   it. If the owner picks another option, go back to step 3 with that\n   option, rewrite `## Approach`, and ask again. On any other no, write the\n   owner's words under `## Corrections` first, empty `## Approach` below its\n   heading, go back to `accord-intent` step 8, and restart this stage at\n   step 2.\n   `accord approve` runs only on a yes to the sections as shown. Never run\n   `accord approve` without the owner's yes in this conversation.\n\n6. Next: `accord-plan`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- A later change to Intent, acceptance criteria, Vetoes, Decisions,\n  Corrections, or Approach needs a new yes from the owner and a new\n  `accord approve <id>`.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "build/SKILL.md": "---\nname: accord-build\ndescription: Use when a lane M ticket has a plan that passed accord gate plan and needs building. Dispatches one fresh executor per task from accord brief, runs the affected tests itself, and records each task with accord task-done.\nlicense: MIT\nkind: skill\nloads: [shared/ask.md]\n---\n\nThis stage builds the plan one task at a time. You run it in the main\nsession and orchestrate: executors write the code.\n\n## Steps\n\n1. Run `accord anchor`. It names the next task. If\n   `git log -1 --format=%s -- accord/tickets/<id>/plan.md` does not print\n   `plan: <id> ready`, or `git status --porcelain` on `plan.md` prints\n   anything, the plan stage has not finished: load `accord-plan` and\n   resume there instead of building.\n\n2. **Dispatch.** For each task in `plan.md` without a line in\n   `accord/tickets/<id>/ledger.md`, in order, one at a time: run\n   `accord brief <id> <n>` into a file outside the working tree (for\n   example the system temp directory), so it is never committed, and\n   dispatch a fresh `accord-executor` with the path of that file only.\n   Never pass chat history.\n\n3. **Record.** When it reports, run the affected tests yourself: the\n   `tests.affected` command from `accord/config.yml`, with `{files}`\n   replaced by the paths on the task's `files:` line. Then run\n   `accord task-done <id> <n>`. The executor's claim alone records\n   nothing.\n   - It refuses because a `verify:` case failed or is missing: dispatch\n     a fresh executor with the same brief plus the reasons it printed.\n     If it refuses that way again after that dispatch, load `accord-debug`\n     instead of dispatching again.\n   - It refuses because the report is missing or older than the commit:\n     the `tests.affected` command does not write the report `tests.report`\n     names. Tell the owner; do not loop.\n   - It writes the `@test:` tag of each scenario a `verify:` id marks\n     with `(@ac-n)`. It refuses because a scenario already carries a\n     different `@test:` tag: ask the owner; never an executor or `accord-debug`.\n   - It writes the ledger line: copy every Ruling in the executor's\n     report into `accord/tickets/<id>/ledger.md` under `## Rulings`, then\n     commit the ticket together with `accord/tickets/<id>/ledger.md`.\n   - A ticket whose recorded tasks predate the tag writer: run\n     `accord task-done <id> <n>` again for each recorded task.\n\n4. **Blocked.**\n   - `BLOCKED` with a question that touches intent, a veto, a criterion,\n     or a public interface: ask the owner.\n   - `BLOCKED` on a test that seems wrong: a criterion test is the\n     owner's, so ask the owner; any other test is a plan gap and goes back\n     to `accord-plan`. Never edit the test yourself.\n   - `BLOCKED` on an architecture change: go to step 6. `BLOCKED` after\n     three failed attempts: ask the owner, with what was tried; never\n     dispatch a fresh executor for more tries. A new package: ask the\n     owner.\n   - `BLOCKED: context`: dispatch a fresh executor with the same brief\n     plus the diff and the ledger so far.\n   - `NEEDS_CONTEXT`: answer, and dispatch again.\n\n5. **Files.** A file outside the task's `files:` line must be declared\n   in the report with a reason. When you accept it, record a Ruling.\n\n6. **Change of course.** When the approved approach cannot work, stop.\n   Write a change note under the ticket's `## Approach`: what failed,\n   which finished tasks still hold, and the proposed new approach. Ask the\n   owner for a new yes; on yes run `accord approve <id>`, then\n   `accord-plan`'s re-plan covers only the tasks the change touches.\n   Never re-plan quietly.\n\n7. **Plan changed.** When `accord task-done` says `plan.md` changed,\n   never run `accord gate plan` to clear it. Show the owner the diff of\n   `plan.md`. If the owner made the change, `accord-plan` reviews it\n   (critic, then `accord gate plan`); otherwise restore `plan.md` with the\n   owner's yes and dispatch again. Only `accord-plan` changes the plan. Never run\n   `accord tests baseline` here; only the plan stage asks the owner about it.\n\n8. When every task has a ledger line, next: `accord-review`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary:\n  the executor gets it inside its brief.\n- The main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "debug/SKILL.md": "---\nname: accord-debug\ndescription: Use when a lane M ticket's work behaves unexpectedly, a test fails for a reason nobody has shown, or a fix did not work. Finds the root cause with a debugger before any fix, fixes it once through a fresh executor test first, and keeps its state in debug.md.\nlicense: MIT\nkind: skill\nloads: [shared/ask.md]\n---\n\nThis stage finds a root cause before anything is fixed. You run it in the\nmain session and orchestrate: debuggers investigate, executors fix.\n\n## Steps\n\n1. Run `accord anchor`. The stage it prints is the one this returns to.\n\n2. **State.** Everything this stage learns lives in\n   `accord/tickets/<id>/debug.md`: the symptom, the hypotheses, the\n   probes and what they showed, and each fix tried with its count. It\n   survives compaction; after one, read it before anything else. Start\n   each episode by appending `## Episode <n>` to it; the episode is open\n   while the last `## ` heading in the file is not `## Resolved`.\n\n3. **Root cause.** No fix before a root cause. Dispatch a fresh\n   `accord-debugger` with the path of the ticket file and the failing\n   command and its output. It writes `debug.md`:\n   - competing hypotheses, each with evidence for and against, ranked\n     before any is tested;\n   - one hypothesis is always that the test or measurement itself is\n     wrong;\n   - the first test is the cheapest probe that separates the top two.\n\n   It returns the root cause with evidence, the failing reproduction\n   test it proposes, and the hypotheses ruled out. Commit `debug.md`.\n   A root cause without evidence is a hypothesis: dispatch once more with\n   the path of `debug.md`. A second return without evidence (flaky,\n   timing, cannot reproduce): stop and ask the owner with the ranked\n   hypotheses and what was ruled out.\n\n4. **Fix.** The main session never edits product code: the fix goes\n   through `accord-build`'s executor path. Note the HEAD sha. Write a\n   brief file outside the working tree: copy the ticket file byte for\n   byte (never retype it), then append the root cause, its evidence, and\n   the reproduction test. The executor starts with that failing\n   reproduction test, greps every caller of what it changes, and fixes\n   the root cause once in shared code, never at each caller. Dispatch a\n   fresh `accord-executor` with its path. `BLOCKED` on a test that is\n   not a criterion test: ask the owner, as there is no plan task to\n   re-plan. Route every other stop as `accord-build` does.\n\n5. **Check.** Run the `tests.affected` command over the files changed\n   since the noted sha. Copy every Ruling in the executor's report into\n   `accord/tickets/<id>/ledger.md` under `## Rulings`. Record the fix and\n   its result in `debug.md`, then commit `debug.md` with the ledger.\n\n6. **Failed fix.** A fix that leaves the symptom, or the reproduction\n   test failing, counts one in `debug.md`. After one failed fix, dispatch\n   one `accord-debugger` per remaining hypothesis, in parallel, each\n   with the paths of the ticket file and `debug.md` and its one\n   hypothesis. In a parallel round they write nothing and return\n   evidence; you merge every result into `debug.md` and commit it. Then\n   back to step 4 with the root cause the evidence supports. No\n   hypothesis left: back to step 3.\n\n7. **Three.** After three failed fixes, stop: never a fourth. Each fix\n   uncovering a new problem elsewhere means the architecture is wrong,\n   not the hypothesis. Write the architectural question in `debug.md`\n   and ask the owner, with what was tried. This count is this stage's\n   own; an executor's three attempts at one problem inside a task also\n   end at the owner.\n\n8. **Resolved.** Append `## Resolved` to `debug.md`, one line: the root\n   cause and the fix commit, or the owner's decision. Commit it.\n\n9. Next: return to the stage `accord anchor` prints. When that is\n   `accord-build`, start at its step 3 for the task that entered debug:\n   run the affected tests and `accord task-done` before dispatching\n   anything.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary:\n  an executor gets it inside its brief.\n- The main session orchestrates and never edits product code.\n- A winning hypothesis that a criterion test is wrong is the owner's\n  call: ask. Never edit the test yourself.\n- \"It's probably X\", \"just try X\", and \"one more attempt\" mean back to\n  step 3, except after three failed fixes: step 7.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "designer/SKILL.md": "---\nname: accord-designer\ndescription: Use when a ticket is marked ui and the Ready gate is asking for a design reference. Establishes whether the ticket has an interface, picks a design link or a prototype from the profile, produces the missing one, and re-runs the gate.\nlicense: MIT\nkind: role\nloads: [shared/prototype.md]\n---\n\nDesigner is a stage a ticket passes through, not a job title. The same person\nand agent move through intent, design, and implementation in turn. This stage\nends when the ticket carries the design reference the gate was asking for.\n\n## Steps\n\n1. Run `accord gate ready <id>` and read the reasons it prints. Those reasons\n   are the whole brief for this stage. If none of them is about design, there\n   is nothing to do here — hand the ticket back to the stage that owns the\n   reason rather than inventing work.\n\n2. Read `ui:` in the frontmatter of `accord/tickets/<id>.md`.\n\n   - `ui: false` — stop. A ticket with no interface has no design reference to\n     produce.\n   - `ui: true` — continue.\n\n3. Read `profile:` in `accord/config.yml` and take the matching branch.\n\n   - `profile: build` — the ticket needs a design link or a prototype. When\n     the design already exists, put its link in `design:` in the ticket\n     frontmatter. When it does not, read `./prototype.md` and build one.\n   - `profile: maintain` — the ticket needs\n     `accord/assets/<id>/prototype.html`. Read `./prototype.md` and build it\n     from the styles the project already has. A prototype invented from new\n     styles is a redesign nobody asked for.\n\n4. Run `accord gate ready <id>` again. The reason you came here for is gone,\n   or the work is not finished.\n\n## Boundaries\n\nYou own the design reference and nothing else. Acceptance criteria belong to\nthe stage that wrote them: a scenario you disagree with goes to\n`## Open questions` in the ticket, never into an edit of\n`## Acceptance criteria`.\n",
  "intent/SKILL.md": "---\nname: accord-intent\ndescription: Use when a lane M ticket needs its intent captured, or when /accord routes a new request here. Runs the intent interview that writes the ticket's Intent, acceptance criteria, Vetoes, Decisions, and Corrections, so later stages cannot drift from what the owner meant.\nlicense: MIT\nkind: skill\nloads: [shared/ask.md]\n---\n\nThis stage writes down what the owner means, in the ticket, before anyone\nplans or builds. You run it in the main session.\n\n## Steps\n\n1. Run `accord anchor`. If the ticket file does not exist yet, `/accord`\n   creates it first: start there.\n\n2. **Look before asking.** Dispatch `accord-scout` with the path of\n   `accord/tickets/<id>.md` and the questions the code can answer. Never ask\n   the owner what the code answers. A question about an existing project\n   cites the file that prompted it.\n\n3. **Confirm the parts.** Before the first score, list the request's\n   top-level parts and ask the owner to confirm them.\n\n4. **Score ambiguity** from 0 to 1 on four dimensions: goal, scope boundary,\n   constraints, acceptance; 0 is unambiguous, 1 is unknown. Show the owner\n   the four scores after each round. No dimension may stay above 0.4. Stop\n   when the total (the mean) is 0.2 or less with no dimension above 0.4, or\n   when the owner says \"enough\".\n   Before you stop, ask once for the smallest version that still counts as\n   done.\n   On \"enough\", write `Ruling: interview stopped by the owner at <score>`\n   into `accord/tickets/<id>/ledger.md` under `## Rulings`.\n\n5. **One question per message**, aimed at the dimension with the highest\n   score; which kind of question to ask, and how, follows `./ask.md`.\n\n6. **Write the ticket** `accord/tickets/<id>.md`, each section as follows:\n\n   | Section | Content |\n   |---|---|\n   | `## Intent` | at most five lines: why, for whom, success measure, non-goals; you draft, the owner approves |\n   | `## Acceptance criteria` | two to five Gherkin scenarios, `@ac-1` … `@ac-n`; you draft, the owner approves |\n   | `## Vetoes` | what the owner forbids, in the owner's words |\n   | `## Decisions` | settled answers in the owner's words: `- D-01 <decision> — \"<the owner's sentence>\"` |\n   | `## Corrections` | every \"no, I meant…\", verbatim, append-only, written before any other action |\n   | `## Open questions` | each unanswered question as an unchecked `- [ ]` item |\n\n7. **Write back** your understanding. Separate what the owner said from what\n   you assumed, and invite correction.\n\n8. **Audit once.** Dispatch `accord-auditor` with only the path of the\n   ticket file. A criterion it reads two ways goes back to the owner as a\n   question. Then commit `accord/tickets/<id>.md`, with the ledger if it\n   changed.\n\n9. **The owner's yes.** Run `accord show <id> --approval`; if it fails, stop and tell the\n   owner. Paste its output unchanged, as Markdown, not inside a code block; below it put a horizontal rule, a\n   heading \"In plain words\" written in the chat language, and one line per scenario that begins with its ac-n\n   and says in plain words what it means; ask for an explicit yes, and on yes commit the ticket with\n   the owner's answer quoted in the commit message. That commit holds `accord/tickets/<id>.md`, with the ledger\n   if it changed, and uses `--allow-empty` when nothing changed. On a no, write the owner's words under\n   `## Corrections` first, rewrite the sections they touch, take a changed criterion back to step 8, and show\n   the text again.\n\n10. Next: `accord-approach`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- A correction goes into `## Corrections` verbatim before any other action.\n  A correction that exists only in the conversation is lost at the next\n  compaction.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "plan/SKILL.md": "---\nname: accord-plan\ndescription: Use when a lane M ticket has an approved approach and needs a plan. Has the planner write plan.md task by task, checks it with accord gate plan and the critic, and runs the full test suite on the baseline before build.\nlicense: MIT\nkind: skill\nloads: [plan/baseline.md, plan/critique.md, shared/ask.md]\n---\n\nThis stage turns the approved approach into tasks an executor can finish\none at a time. You run it in the main session. The owner does not need to\nread the plan.\n\n## Steps\n\n1. Run `accord anchor`. When `plan.md` exists but the last commit that\n   touched it is not `plan: <id> ready`, or `git status --porcelain` on\n   `plan.md` prints anything, resume at step 4, counting rounds from the\n   `plan: <id> round` commits in `git log` since the last\n   `plan: <id> ready`, if any, and reading `plan-review.md` as `./critique.md` says.\n\n2. **Plan.** Run `git rev-parse HEAD`, read `review.mode` in\n   `accord/config.yml` (absent counts as `human`), and dispatch\n   `accord-planner` with the path of `accord/tickets/<id>.md`, that commit,\n   and the mode. It writes `accord/tickets/<id>/plan.md` with frontmatter\n   `baseline: <git rev-parse HEAD>` and one `## Task <n>: <title>` section\n   per task. Each task carries a `covers:` line, a `files:` line, and a\n   `verify:` line, then prose for the executor: the interface (consumes,\n   produces) and the test written first. A task fits in about half an\n   executor's context; the planner splits anything larger. Only the first\n   plan sets `baseline:`. In `verify:`, write `(@ac-n)` after the id of the\n   test that proves scenario `@ac-n`.\n\n   **Re-plan**, entered from a change of course or a review plan gap:\n   dispatch the planner with the ticket path, the `baseline:` already in\n   `plan.md`, the mode, the paths of `plan.md` and the ledger, and the\n   change note or plan gap. `baseline:` never changes; every task with a\n   ledger line keeps its text and number; each new or changed task is\n   numbered after the highest existing number; `(new)` stays relative to\n   the baseline. Steps 4 to 6 run as usual, step 7 does not re-run the\n   baseline tests, and step 8 commits again.\n\n3. **Slices.** Under `review: human` the planner groups tasks into slices:\n   each slice is one pull request covering a stated subset of the\n   acceptance criteria, green on its own. The planner writes each slice\n   into `plan.md`: the tasks it holds and the criteria it covers. Under\n   `review: outcome` it is one branch, no slices.\n\n4. **Gate.** Run `accord gate plan <id>` and fix what it prints, then run\n   it again until it passes. On a pass it writes `plan_hash:` into\n   `plan.md`. A plan changed after that, by a critic round or anything\n   else, must pass `accord gate plan <id>` again before `accord task-done`\n   records a task, so re-run the gate after every revision. A question it asks about the tests\n   baseline is answered at step 7; never create `accord/tests-baseline.txt` earlier. A gate\n   failure you cannot fix counts as an open finding in step 6.\n\n5. **Critique.** Run the loop in `./critique.md`: how many `accord-critic` agents\n   read, and what, which findings `accord-planner` fixes, and when the loop ends.\n\n6. **Rounds.** At most three revision rounds. If a Must or Should in\n   `plan-review.md` is still `open` or `unverified`, or `accord gate plan <id>` still fails, after the third, stop and tell the owner what is still\n   open, and show the revision with the fewest Must findings: its round\n   and its commit, read from `git log` since the last `plan: <id> ready`,\n   if any. Never continue on\n   a failing plan.\n\n7. **Baseline tests.** Before the first build commit, run the\n   `tests.full` command from `accord/config.yml` at the current HEAD, and\n   only while `git diff --stat <baseline> HEAD` shows no change outside\n   `accord/`. Never check out, stash, reset, or clean to reach the\n   baseline. If product code has changed since the baseline, ask the\n   owner. Show the owner every failing case; the owner decides whether it\n   is fixed first or tracked as its own ticket. Never ignore a failing\n   case on your own. When `tests.report` is set and\n   `accord/tests-baseline.txt` is absent, follow `./baseline.md`.\n\n8. **Finish.** If `git status` shows `accord/tests-baseline.txt` new, commit it\n   alone first and add its Ruling if absent, per `./baseline.md`. Append a `## Closed` line to `plan-review.md`. Commit `plan.md` and `plan-review.md`, with the ledger if it changed, with the\n   subject `plan: <id> ready`. That commit marks the plan finished;\n   `accord-build` checks for it.\n\n9. Next: `accord-build`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "plan/baseline.md": "---\nkind: reference\n---\n\n# The tests baseline\n\nWhen `accord/config.yml` has no `tests.report`, skip this file: ask nothing.\n\nWhen `accord/tests-baseline.txt` is absent, and only after the owner has decided every failing case at the baseline, as step 7 says, ask the owner before running `accord tests baseline`. The baseline then lists the failing cases too.\n\nShow the number of test cases no scenario names, and up to five of them, read from the lines `accord lint` prints for them, never a hand count. The owner chooses one of: create it, do not create it, or stop. Not creating it is allowed: `accord gate plan` keeps asking on every run and nothing records the choice.\n\nWhen `tests.full` wrote no report, stop and tell the owner; never write a report, and never run `accord tests baseline` against an old one.\n\nWhen `accord tests baseline` refuses because the report is older than the last commit: if `git diff --stat <baseline> HEAD` shows no change outside `accord/`, run `tests.full` once more and retry once; otherwise stop and tell the owner.\n\nOn a yes, run `accord tests baseline` and commit `accord/tests-baseline.txt` in a commit of its own, holding that file alone, never with the `plan: <id> ready` commit of step 8, so it can be picked onto its own pull request. Then write into `accord/tickets/<id>/ledger.md`, under `## Rulings`:\n\n`Ruling: accord/tests-baseline.txt created at the plan baseline on the owner's yes — no task's files: line names it, so review would otherwise list it as undeclared — cost if wrong: review reports it as Extra`\n\nThe ledger goes in the `plan: <id> ready` commit, so the baseline commit still holds that file alone. A resumed run that finds the file written but not committed does both at step 8: commit the file alone, then add the Ruling when the ledger lacks it, before the `plan: <id> ready` commit.\n\nOn a team, the file reaches the main branch in its own small pull request, holding that file alone, before other tickets plan. On a merge conflict in it, keep only the lines both sides hold, never the union: a dropped case then fails loudly at the gate instead of being exempted silently.\n\nNever create the file in any other step, stage, or agent.\n",
  "plan/critique.md": "---\nkind: reference\n---\n\n# The critique loop\n\nThe main session keeps every critic finding in\n`accord/tickets/<id>/plan-review.md`: one `## Round <n> (whole)` or\n`## Round <n> (diff)` section per round, each finding on one line as\n`<n>. <Must|Should|Nice> — <finding> — <state>`. The state is `open`,\n`fixed`, `deferred` for a Nice, `unverified: <reason>`, `withdrawn`,\n`repeated as <round>.<n>` when a critic carries it on under that number,\n`open, owner: \"<the owner's words>\"` for a fix the owner said to apply,\nor `owner: \"<the owner's words>\"` for one the owner dropped. A finding\nstays `open` or `unverified` until a critic lists it after `fixed:` or\n`withdrawn:`, or the owner drops it; the planner's word alone closes\nnothing. A round with no findings says `No findings`. Only the sections\nafter the last `## Closed` line count; step 8 of the skill appends that\nline.\n\n1. **Read.** Round 1 is `whole` and sized by the plan. Count the\n   `## Task` sections of `plan.md` and judge from the ticket and the plan\n   whether the ticket touches auth, money, migration, or data deletion.\n   Dispatch in parallel, each in a fresh context, mode `plan`, with the\n   paths of the ticket and `plan.md`, naming its lens:\n   - one `accord-critic`, no lens, for a plan of one to three tasks;\n   - two critics for a plan of four or more tasks, lens `criteria`,\n     which checks that the plan reaches the criteria and the Intent, and\n     lens `build`, which checks that an executor can build each task;\n   - one more critic, lens `security`, for a plan of any size whose\n     ticket touches auth, money, migration, or data deletion, so at most\n     three.\n\n   Merge and de-duplicate their findings into one round, numbered within\n   it, before the planner gets them. After a round that reports a Must,\n   or that leaves a Must from an earlier round open or unverified (its\n   section holds a Must, or `<m>` is above zero in step 5), the next\n   round is `whole`, even when the owner dropped that Must: one\n   `accord-critic` in a fresh context, no lens, mode `plan`, with the\n   paths of the ticket, `plan.md`, and `plan-review.md`. After any other\n   round the next is `diff`: write\n   `git diff <that round's commit> -- accord/tickets/<id>/plan.md`, which\n   holds the planner's fix, into a file outside the working tree, and\n   dispatch one `accord-critic` in a fresh context, mode `diff`, with the\n   paths of the ticket, `plan.md`, that file, and `plan-review.md`. A\n   `diff` critic never reads the whole plan.\n2. **Record.** Append the round's section to `plan-review.md` and mark\n   each new finding `open`. Mark `fixed` each finding a critic lists\n   after `fixed:`, and `withdrawn` each one it lists after `withdrawn:`.\n   When a new finding starts `repeats <round>.<n>:`, mark that earlier\n   finding `repeated as <this round>.<n>`. A Nice goes to the ledger\n   under `## Deferred`, marked `deferred`, and never to the planner.\n3. **Owner.** A finding whose proposed fix relies on an API cited only\n   by a URL outside the repository goes to the owner at once, as\n   `./ask.md` says: show the finding, the fix, and the URL, and ask\n   whether to apply or drop it. On apply its state becomes\n   `open, owner: \"<the owner's words>\"`: it goes to the planner with\n   those words, which confirm the API, and closes only when a critic\n   lists it after `fixed:`. On drop its state becomes\n   `owner: \"<the owner's words>\"`, which closes it.\n4. **Converged.** The loop ends only on a round that reports no Must\n   and no Should and leaves no Must or Should open or unverified, and\n   only when the last `accord gate plan <id>` passed: go to step 7 of\n   the skill.\n5. **Fix.** Otherwise commit `plan.md` and `plan-review.md` with the\n   subject `plan: <id> round <n>, <m> Must, <s> Should`, where `<m>` and\n   `<s>` count the Musts and the Shoulds after the last `## Closed` line\n   that are `open` or `unverified` once this round is recorded; the next\n   `diff` round reads from that commit. Dispatch `accord-planner` with the\n   ticket path, the baseline, the mode, the path of `plan-review.md`, and\n   every Must and Should that is `open` or `unverified`, never a Nice,\n   each labelled `<round>.<n>` and listed with the owner's words it holds.\n   The planner fixes every one and replies by that label. Write each\n   `unverified: <reason>` it replies into the state of the finding with that\n   label; a finding it reports fixed stays `open` until a critic lists it\n   after `fixed:`. Then go back to step 4 of the skill.\n",
  "review/SKILL.md": "---\nname: accord-review\ndescription: Use when every task of a lane M ticket has a ledger line and the work needs review. Dispatches reviewers on the review package, fixes patch findings through fresh executors until no Must is open and every Should is fixed, runs one final reviewer, and records each round in review.md.\nlicense: MIT\nkind: skill\nloads: [review/record.md, shared/ask.md]\n---\n\nThis stage reviews the built work against the ticket until it converges.\nYou run it in the main session and orchestrate: reviewers find, executors\nfix.\n\n## Steps\n\n1. Run `accord anchor`.\n\n2. **Package.** Run `accord review-package <id>` into a file outside the\n   working tree. It holds the commits, the stat, and the diff from the\n   plan's `baseline:`, and lists under `## Undeclared files` every changed\n   file no task's `files:` line names. The review unit is the whole\n   ticket, whatever `review.mode` in `accord/config.yml` says.\n\n3. **Reviewers.** Choose by the unit's diff size and risk:\n   - up to about 500 changed lines: one `accord-reviewer`, lens `both`;\n   - about 500 to 1500: an `intent` and a `quality` reviewer, in parallel;\n   - over about 1500: split by area times lens, plus one `integration`\n     reviewer reading only the interfaces and links between areas;\n   - auth, money, migration, or data deletion: add a `security` reviewer,\n     at any size.\n\n   Name the lens in each dispatch. Every reviewer gets the paths of the\n   ticket file, the review package, and `accord/tickets/<id>/ledger.md`;\n   the approach is the ticket's `## Approach`. The executor's report is\n   context, never evidence.\n\n4. **Classify.** Merge and de-duplicate the findings. Before fixing, mark\n   each one `patch`, `plan-gap`, or `intent-gap`.\n   - Fix every Must and Should marked `patch` through `accord-build`'s\n     executor path. Note the HEAD sha. Write a brief file outside the\n     working tree: copy the ticket file byte for byte (never retype it),\n     then append the findings to fix. Dispatch a fresh `accord-executor`\n     with its path, and route its stops as `accord-build` does.\n   - When it reports, run the `tests.affected` command over the files the\n     fix touched, or `tests.full` when `tests.affected` is not configured or\n     finds no test file. If it fails, dispatch a fresh executor with the same\n     brief plus the failing output, in the same round.\n   - Copy every Ruling in its report, and each file outside the plan you\n     accept as a Ruling naming the file and its reason, into\n     `accord/tickets/<id>/ledger.md` under `## Rulings`; commit the ledger.\n   - When the round reported a Must, re-review only the fix diff:\n     `accord review-package <id> --base <the noted sha>` into a file\n     outside the working tree, one reviewer, lens `both`. When it reported\n     only Should findings, no reviewer is dispatched again for that fix:\n     that command passing checks it.\n   - A plan gap goes back to `accord-plan` as a re-plan, where the critic\n     runs again.\n   - An intent gap stops the run and asks the owner.\n   - Nice findings go to the ledger under `## Deferred`, not fixed.\n\n5. **Converged** means no Must is open and every Should is fixed with that\n   command passing. If round 3 still finds\n   a new Must, say whether it traces to the ticket or the plan; if it\n   does, ask the owner before round 4.\n\n6. **Cap.** At most five rounds. A round at or after\n   `escalation.fix_round_tier_up` in `accord/config.yml` (default 4)\n   dispatches a fresh executor one model tier above the executor's\n   configured model, passed as `model` on the dispatch itself: `haiku`,\n   then `sonnet`, then `opus`; `opus` stays `opus`. At the cap, stop and\n   report the open findings to the owner; never report the work finished.\n\n7. **Final review.** After convergence, one fresh `accord-final-reviewer`\n   reads the whole review package once (over about 1500 changed lines,\n   dispatch it with lens `integration`). If it finds a Must:\n   one fix and one scoped re-review, as in step 4. If it finds only Should\n   findings, fix them and run that command as in step 4, with no\n   re-review. If a Must is still\n   open after that, stop and ask the owner.\n\n8. **Record.** Write every round to `accord/tickets/<id>/review.md` as\n   `./record.md` says, ending `verdict: converged`, or, when the owner\n   accepts any stop with findings still open, `verdict: accepted-by-owner`\n   followed by the owner's sentence quoted.\n   Commit it.\n\n9. Next: `accord-verify`.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary:\n  an executor gets it inside its brief.\n- The main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
  "review/record.md": "---\nkind: reference\n---\n\n# The review record\n\n`accord/tickets/<id>/review.md` holds one section per review round, in\norder, and ends with the verdict.\n\n```\n## Round <n>\n\nMust|Should|Nice <n> [patch|plan-gap|intent-gap]: <finding> — <file:line> — fixed in <sha> | deferred | open\n```\n\n- One `## Round <n>` section per round, the final review included, each\n  listing that round's findings after merging and de-duplication, numbered\n  within the round.\n- Each finding carries its severity, its class, what it is, where it is,\n  and what became of it: `fixed in <sha>` with the fix commit, `deferred`\n  for a Nice finding written to the ledger under `## Deferred`, or `open`.\n- A round with no findings says `No findings`.\n\nThe single last line of the file is the verdict:\n\n- `verdict: converged` when, after the final review, no Must is open and\n  every Should is fixed with that command passing: `tests.affected` over\n  the files the fix touched, or `tests.full` when `tests.affected` is not\n  configured or finds no test file;\n- `verdict: accepted-by-owner \"<the owner's sentence>\"` when the run\n  stopped with findings still open, at the cap or after the final\n  re-review, and the owner accepted them, quoting what the owner said.\n\nNothing follows the verdict line.\n",
  "shared/ask.md": "---\nkind: reference\n---\n\n# Asking the owner\n\nA question that needs context to be understood is asked in plain chat, never in\na question dialog, because the dialog hides the chat written before it: a few\nplain sentences of context, then the question, then lettered options, each\nsaying what happens if it is chosen, the recommended one first, with one\nsentence on why it is recommended. A question dialog is used only when the\nquestion and its options are understood on their own in one line, such as\n'Commit now?'.\n\nAsk multiple choice when you can list two to four exclusive options, each with\na consequence drawn from the code or the ticket; ask an open question, with no\noptions, when the answer is in the owner's head, such as why, for whom, what\nsuccess looks like, or what hurts today; offer a short menu only when the owner\nis stuck on an open question.\n\nExplain in plain words for an owner who reads no code: a file path or a symbol\nis only a pointer, never the explanation, and every id such as ac-2 or D-03\ncarries a short gloss.\n",
  "shared/prototype.md": "---\nkind: reference\n---\n\n# Producing a prototype\n\nA `ui: true` ticket needs something a reviewer can look at before the code\nexists. In the `maintain` profile that something is\n`accord/assets/<id>/prototype.html`, and it is derived from what the project\nalready looks like — not from a fresh idea of what it could look like.\n\n## 1. Find the styles the project already has\n\nBefore writing any markup, find where the look of this project is defined.\nLook for, in roughly this order:\n\n- the path named under `design.tokens` in `accord/config.yml`, if one is set;\n- a stylesheet or variables file the application loads on every page;\n- a utility-class configuration, if the project styles that way;\n- a components or design-system folder.\n\nRead what you find. You are looking for the names the project uses for its\ncolours, spacing, radii, and type — those names are what the prototype spends,\nand inventing new ones is a redesign the ticket did not ask for.\n\nIf you find nothing, say so in the ticket's `## Open questions` and keep\ngoing: a prototype built from nothing has to record what it was built from\ninstead.\n\n## 2. Start from a single HTML file\n\nOne HTML file: a comment block at the top, an empty body. The comment block\nnames the ticket, a `Derived from:` line for what step 1 found, and the owner.\nBuild the page underneath it. One file, no build step, no assets directory —\na reviewer opens it in a browser and it works.\n\n## 3. Put it where the gate looks\n\n`accord/assets/<id>/prototype.html`, with `<id>` the ticket id. That folder is\nthis stage's own; nothing else writes into it.\n\n## 4. Run `accord lint` and fix what it reports\n\nDo not work from memory of the rules — run it, read the reasons, and fix what\nit names.\n\nA finding you disagree with is a question, not a licence: write it into the\nticket's `## Open questions` and stop, rather than working around the rule.\n\n## 5. Re-run the gate\n\n`accord gate ready <id>` is the only thing that says whether the ticket now\nhas what it was missing.\n",
  "verify/SKILL.md": "---\nname: accord-verify\ndescription: Use when a lane M ticket's review.md ends with a verdict and the work needs verifying. Runs the full suite, has a fresh verifier write verification.md, builds the owner's report, and runs accord gate done once the owner has approved verified.\nlicense: MIT\nkind: skill\nloads: [shared/ask.md]\n---\n\nThis stage checks the built work against the ticket and hands it to the\nowner. You run it in the main session and orchestrate: the verifier\njudges, the owner decides.\n\n## Steps\n\n1. Run `accord anchor`.\n\n2. **Suite.** First commit everything, `review.md` included, so the\n   working tree is clean: that commit is the one verified. Run the\n   `tests.full` command from `accord/config.yml` at it, so the report\n   `tests.report` names is fresh.\n\n3. **Verifier.** Dispatch `accord-verifier` in a fresh context with the\n   path of `accord/tickets/<id>.md`. It writes\n   `accord/tickets/<id>/verification.md` and nothing else.\n\n4. **Report.** Build the owner's report in chat from `verification.md`,\n   the report `tests.report` names, and `accord/tickets/<id>/ledger.md`:\n   - one line per criterion: pass or fail, with its evidence (the test and\n     its output, or a screenshot for UI);\n   - three to five \"try this\" steps that take the owner about two minutes;\n   - every Ruling under the ledger's `## Rulings`, ordered by its\n     cost if wrong, highest first;\n   - the deferred items under the ledger's `## Deferred`;\n   - what was not checked, including every criterion the verifier\n     recorded as `blocked`;\n   - slow tests: the slowest cases in the report, with their times.\n\n5. **Owner.** Read `review.mode` in `accord/config.yml` (absent counts as\n   `human`).\n   - Under `review: outcome`, after the report, ask the owner one\n     question with two choices, approve or not yet. The question names\n     the criteria to tick, the commit verified, and the three values you\n     will write. Only on an explicit approve, write `verified:` with those\n     criteria, `verified_hash:` set to the current `ac_hash:`, and\n     `verified_commit:` to the commit verified. Silence, an unclear\n     answer, or a yes given before the report is not an approve: ask\n     again. `## Verification notes` is not required.\n   - Under `review: human` the 0.1.0 human layer stays: a person ticks\n     `verified:` by hand, with the same two values, and writes\n     `## Verification notes`. You never write any of them.\n   - A `fail` or `blocked` criterion: show the owner. A failing criterion\n     goes back to `accord-build` as a fix, or the owner decides; it is\n     never ticked past.\n\n6. Run `accord gate done <id>` and work from what it prints. Leave\n   `verification.md` and the tick uncommitted until it passes;\n   the notice that the review file has no author yet is expected and no\n   reason to commit earlier. When it passes, commit only\n   `accord/tickets/<id>.md` and `accord/tickets/<id>/verification.md`;\n   under `review: outcome` the commit message quotes the owner's answer.\n\n7. Next: `/accord`, for the next ticket.\n\n## Rules\n\n- Every agent receives the ticket verbatim, by file path, never a summary.\n- The main session orchestrates and never edits product code.\n- Anything touching intent, a veto, an acceptance criterion, or a public\n  interface stops the run and asks the owner. Every other decision is a\n  Ruling in `accord/tickets/<id>/ledger.md` under `## Rulings`:\n  `Ruling: <what> — <why> — <cost if wrong>`.\n  Read `./ask.md` before any question to the owner.\n",
} as const;
export type SkillKey = keyof typeof skills;
